  function chooseTool(name,options={}){
    if(editing)finishInline();
    if(name==='ai'){setPanel('ai');setRightOpen(true);return;}
    if(name==='image'){imageRef.current?.click();return;}
    if(name==='camera'){cameraRef.current?.click();return;}
    if(name==='file'){fileRef.current?.click();return;}
    if(['ruler','protractor','triangle-ruler','coordinate-grid','number-line'].includes(name)){
      const sizes={ruler:[400,65],protractor:[340,170],'triangle-ruler':[260,260],'coordinate-grid':[360,360],'number-line':[450,65]},[width,height]=sizes[name];
      addObject({type:name,x:(pw-width)/2,y:Math.min(ph-height-40,360),width,height,data:{opacity:.85,color:'#8060c9',angle:45,length:10,markerAngle:45}});setPanel('properties');return;
    }
    if(name==='table'){openModal('table',{rows:3,cols:3,cells:Array.from({length:3},()=>Array(3).fill(''))});return;}
    if(name==='formula'){openModal('formula',{latex:'x^2 + y^2 = r^2'});return;}
    if(name==='link'){openModal('link',{title:'',url:'',display:'text'});return;}
    if(name==='sticker'){openModal('sticker');return;}
    if(name==='code'){setTextOptions(o=>({...o,variant:'code'}));setFont('JetBrains Mono');setFontSize(16);setTool('text');setSelected([]);return;}
    if(['diagram','mindmap'].includes(name)){insertDiagram(name);return;}
    if(options.penType)setPenType(options.penType);if(options.shape)setShape(options.shape);
    if(options.variant){setTextOptions(o=>({...o,variant:options.variant}));if(options.variant==='heading'){setFontSize(34);setBold(true);}else{setFontSize(22);setBold(false);}}
    setTool(name);setSelected([]);setPanel('properties');
  }
