  async function importFile(file){if(!file)return;if(file.type!=='application/pdf'){await importAttachment(file);return;}setBusy(true);try{const {openPdf,renderPdfPage}=await import('../../utils/pdfPages');const doc=await openPdf(new Uint8Array(await file.arrayBuffer()));if(doc.numPages>60)throw new Error('Mỗi lần chỉ nhập tối đa 60 trang PDF để bảo vệ bộ nhớ.');const added=[];for(let i=1;i<=doc.numPages;i++){const rendered=await renderPdfPage(doc,i);const p=createPage(book.id,book.pages.length+i);p.title=`${file.name.replace(/\.pdf$/i,'')} · ${i}`;p.paper={...p.paper,type:'blank',orientation:rendered.width>rendered.height?'landscape':'portrait'};p.background=rendered.src;added.push(p);}await doc.destroy();commit(b=>({...b,pages:[...b.pages,...added]}));setPageId(added[0].id);notify?.(`Đã nhập ${added.length} trang PDF. Bạn có thể viết lên từng trang.`);}catch(e){notify?.(e.message||'Không thể nhập PDF.','error');}finally{setBusy(false);if(fileRef.current)fileRef.current.value='';}}
